/**
 * A Button preset that starts and stops recording (`design/components/record-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/record-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentMember,
  agentPress,
  claimSlot,
  clockTime,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/record-button.module.css'
import Button from './Button'

export interface RecordButtonProps {
  disabled?: boolean
  /**
   * The seconds the application has recorded, drawn as m:ss beside the mark while recording. It
   * is not announced, because a time read out every second interrupts everything else.
   */
  elapsed?: number
  /**
   * The Button's name while not recording: "Record a voice message".
   */
  label: string
  /**
   * The input level from 0 to 1, drawn as the size of the mark's halo while recording. It is
   * never the only sign of recording: the glyph, the frame, the name and the time say it too.
   */
  level?: number
  /**
   * The locale the time's numerals are written in; the page's own when absent.
   */
  locale?: string
  /**
   * A press while not recording: the application starts recording.
   */
  onStart?: () => void
  /**
   * A press while recording: the application stops.
   */
  onStop?: () => void
  /**
   * The application is recording. The member draws it and never sets it.
   */
  recording?: boolean
  /**
   * Button's sizes without `lg`. A record control sits beside a field, not as a page's main
   * action.
   */
  size?: 'sm' | 'md'
  /**
   * The Button's name while recording: "Stop recording".
   */
  stopLabel: string
}

/** A Button preset that starts and stops recording. */
export default function RecordButton(given: RecordButtonProps): JSX.Element {
  const props = mergeProps(
    { recording: false, disabled: false, size: 'md' } as Defaults<
      RecordButtonProps,
      'recording' | 'disabled' | 'size'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const root = elementRef<HTMLElement>()
    const share = createDerived(() =>
      props.level !== undefined && Number.isFinite(props.level)
        ? Math.min(1, Math.max(0, props.level))
        : 0,
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'RecordButton',
        element: () => root.value?.querySelector('button'),
        state: () => ({ recording: props.recording, disabled: props.disabled }),
        actions: {
          stop: () =>
            (() => {
              if (!props.recording) throw new Error('Nothing is recording.')
              agentPress(root.value?.querySelector('button'))
            })(),
        },
        withholds: () => root.value,
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <span
        class={styles.root}
        data-state={props.recording ? 'recording' : undefined}
        data-size={props.size}
        data-member="record-button"
        ref={root.attach}
      >
        {props.recording ? (
          <span class={styles.meter} data-record-button-part="meter">
            {/* mark */}
            <span
              class={styles.mark}
              style={{ '--pm-record-button-level': share.value }}
              aria-hidden="true"
            />
            {props.elapsed !== undefined ? (
              <span class={styles.elapsed}>{clockTime(props.elapsed ?? 0, props.locale)}</span>
            ) : null}
          </span>
        ) : null}
        <Button
          variant={props.recording ? 'outline' : 'ghost'}
          tone="neutral"
          size={props.size}
          iconOnly={true}
          icon={props.recording ? 'stop' : 'record'}
          label={props.recording ? props.stopLabel : props.label}
          disabled={props.disabled}
          onClick={() => (props.recording ? props.onStop?.() : props.onStart?.())}
        />
      </span>
    )
  })
}
